'use client';

import { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { Plus, X, ChevronDown, ChevronRight, Image as ImageIcon, Check, Circle, ArrowRight, Star, GripVertical } from 'lucide-react';
import { EditableText } from './EditableText';
import { CourseComponent } from './CourseComponent';
import { ImagePickerModal } from './ImagePickerModal';
import { KnowledgeCheckEditor } from './KnowledgeCheckEditor';
import type { UnitComponent } from './types';

interface EditableCourseComponentProps {
  component: UnitComponent;
  onDataChange: (data: Record<string, unknown>) => void;
}

export function EditableCourseComponent({
  component,
  onDataChange,
}: EditableCourseComponentProps) {
  const { componentName, content } = component;

  // Tabs: real tab UI with add/delete/edit
  if (componentName === 'TabsBlock') {
    return <EditableTabsBlock content={content} onDataChange={onDataChange} />;
  }

  // Accordion: real accordion UI with add/delete/edit
  if (componentName === 'AccordionBlock') {
    return <EditableAccordionBlock content={content} onDataChange={onDataChange} />;
  }

  // Lists: real component + add input at bottom
  if (isListBlock(componentName)) {
    return (
      <EditableListBlock
        component={component}
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Image+text: editable image + Notion-style text
  if (isImageWithTextBlock(componentName)) {
    return (
      <EditableImageWithTextBlock
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Image only: click to change image
  if (componentName === 'ImageBlock') {
    return (
      <EditableImageBlock
        component={component}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // SortingSteps: Notion-style inline editing
  if (componentName === 'SortingStepsBlock') {
    return <EditableSortingStepsBlock content={content} onDataChange={onDataChange} />;
  }

  // MultipleResponse: Notion-style inline editing
  if (componentName === 'MultipleResponseBlock') {
    return <EditableMultipleResponseBlock content={content} onDataChange={onDataChange} />;
  }

  // Knowledge checks: real component + click to open editor
  if (isKnowledgeCheckBlock(componentName)) {
    return (
      <KnowledgeCheckBlockEditor
        component={component}
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Paragraphs & headings: Notion-style always-editable
  if (isParagraphOrHeading(componentName)) {
    return (
      <NotionStyleBlock
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // Other text blocks (highlights, quotes): click to switch to inline editor
  if (isTextBlock(componentName)) {
    return (
      <EditableTextBlock
        component={component}
        componentName={componentName}
        content={content}
        onDataChange={onDataChange}
      />
    );
  }

  // ComparisonCauseEffect: Notion-style inline editing
  if (componentName === 'ComparisonCauseEffectBlock') {
    return <EditableCauseEffectBlock content={content} onDataChange={onDataChange} />;
  }

  // Everything else: show real component as-is
  return <CourseComponent component={component} />;
}

// ─── Category Checks ───────────────────────────────────────────────

function isParagraphOrHeading(name: string): boolean {
  return [
    'ParagraphBlock',
    'ParagraphWithHeadingBlock',
    'ParagraphWithSubheadingBlock',
    'HeadingBlock',
    'SubheadingBlock',
    'HighlightBlock',
    'HighlightNoteBlock',
    'HighlightColumnBlock',
    'HighlightCenterLineBlock',
    'HighlightLeftLineBlock',
    'HighlightBackgroundBlock',
  ].includes(name);
}

function isTextBlock(name: string): boolean {
  return [
    'QuoteBlock',
    'QuoteCenterBorderBlock',
    'QuoteCenterLightBlock',
    'QuoteLeftLightBlock',
    'QuoteLeftBlock',
    'QuoteImageBlock',
  ].includes(name);
}

function isListBlock(name: string): boolean {
  return ['ListBlock', 'CheckboxBlock'].includes(name);
}

function isImageWithTextBlock(name: string): boolean {
  return [
    'ImageWithTextBlock',
    'ImageWithTextLeftBlock',
    'ImageWithTextCenterBlock',
    'ImageWithTextBottomBlock',
    'ImageWithTextTopBlock',
  ].includes(name);
}

function isKnowledgeCheckBlock(name: string): boolean {
  return [
    'MultipleChoiceBlock',
    'FillInTheBlankBlock',
    'MatchingPairsBlock',
    'SortingBlock',
  ].includes(name);
}

// ─── Notion-style: always editable, no click-to-edit ────────────────

function NotionStyleBlock({
  componentName,
  content,
  onDataChange,
}: {
  componentName: string;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const updateField = useCallback(
    (field: string, value: unknown) => {
      onDataChange({ ...content, [field]: value });
    },
    [content, onDataChange],
  );

  if (componentName === 'ParagraphBlock') {
    return (
      <div className="w-full p-4 cursor-text">
        <EditableText
          value={String(content.content || '')}
          onChange={(v) => updateField('content', v)}
          tag="p"
          className="text-base leading-relaxed"
          style={{ lineHeight: '1.75' }}
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'ParagraphWithHeadingBlock') {
    return (
      <div className="w-full p-4 cursor-text">
        <EditableText
          value={String(content.heading || '')}
          onChange={(v) => updateField('heading', v)}
          tag="h2"
          className="mb-4 text-2xl font-bold"
          placeholder="Enter heading..."
          multiline={false}
        />
        <EditableText
          value={String(content.content || '')}
          onChange={(v) => updateField('content', v)}
          tag="p"
          className="text-base leading-relaxed"
          style={{ lineHeight: '1.75' }}
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'ParagraphWithSubheadingBlock') {
    return (
      <div className="w-full p-4 cursor-text">
        <EditableText
          value={String(content.subheading || '')}
          onChange={(v) => updateField('subheading', v)}
          tag="h3"
          className="mb-3 text-lg font-semibold text-gray-700"
          placeholder="Enter subheading..."
          multiline={false}
        />
        <EditableText
          value={String(content.content || '')}
          onChange={(v) => updateField('content', v)}
          tag="p"
          className="text-base leading-relaxed"
          style={{ lineHeight: '1.75' }}
          placeholder="Enter paragraph text..."
        />
      </div>
    );
  }

  if (componentName === 'HeadingBlock') {
    return (
      <div className="w-full p-4 cursor-text">
        <EditableText
          value={String(content.heading || '')}
          onChange={(v) => updateField('heading', v)}
          tag="h1"
          className="text-4xl font-bold"
          placeholder="Enter heading..."
          multiline={false}
        />
      </div>
    );
  }

  if (componentName === 'SubheadingBlock') {
    return (
      <div className="w-full p-4 cursor-text">
        <EditableText
          value={String(content.subheading || '')}
          onChange={(v) => updateField('subheading', v)}
          tag="h2"
          className="text-2xl font-semibold"
          style={{ color: '#6B7280' }}
          placeholder="Enter subheading..."
          multiline={false}
        />
      </div>
    );
  }

  // Highlight variants
  const blockStyle = (content.blockStyle as string) || 'A';
  const highlightStyles: Record<string, { bg: string; color: string }> = {
    A: { bg: 'bg-yellow-100 border-l-4 border-yellow-500', color: '#713f12' },
    B: { bg: 'bg-blue-100 border-l-4 border-blue-500', color: '#1e40af' },
    C: { bg: 'bg-purple-100 border-l-4 border-purple-500', color: '#581c87' },
  };
  const hs = highlightStyles[blockStyle] || highlightStyles.A;

  return (
    <div className={`${hs.bg} p-6 rounded-r-lg my-4 cursor-text`}>
      <EditableText
        value={String(content.highlight || '')}
        onChange={(v) => updateField('highlight', v)}
        tag="p"
        className="text-lg font-medium"
        style={{ lineHeight: '1.6', color: hs.color, fontSize: '18px' }}
        placeholder="Enter highlight text..."
      />
    </div>
  );
}

// ─── Text Block: click-to-edit with real component preview ─────────

function EditableTextBlock({
  component,
  componentName,
  content,
  onDataChange,
}: {
  component: UnitComponent;
  componentName: string;
  content: Record<string, unknown>;
  onDataChange: (data: Record<string, unknown>) => void;
}) {
  const [editing, setEditing] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const updateField = useCallback(
    (field: string, value: unknown) => {
      onDataChange({ ...content, [field]: value });
    },
    [content, onDataChange],
  );

  const handleBlur = useCallback((e: React.FocusEvent) => {
    if (containerRef.current && !containerRef.current.contains(e.relatedTarget as Node)) {
      setEditing(false);
    }
  }, []);

  // Auto-focus the first contentEditable when entering edit mode
  useEffect(() => {
    if (editing && containerRef.current) {
      requestAnimationFrame(() => {
        if (!containerRef.current) return;
        const editable = containerRef.current.querySelector('[contenteditable]') as HTMLElement;
        if (editable) {
          editable.focus();
          // Place cursor at end of text
          const sel = window.getSelection();
          if (sel && editable.childNodes.length > 0) {
            const range = document.createRange();
            range.selectNodeContents(editable);
            range.collapse(false);
            sel.removeAllRanges();
            sel.addRange(range);
          }
        }
      });
    }
  }, [editing]);

  if (editing) {
    return (
      <div ref={containerRef} onBlur={handleBlur}>
        <TextBlockEditor
          componentName={componentName}
          content={content}
          onFieldChange={updateField}
        />
      </div>
    );
  }

  return (
    <div
      className="relative group cursor-pointer"
      onClick={() => setEditing(true)}
    >
      <CourseComponent component={component} />
      <div className="absolute inset-0 bg-transparent group-hover:bg-[#9F80DA]/5 transition-colors flex items-center justify-center opacity-0 group-hover:opacity-100 pointer-events-none">
        <span className="px-3 py-1.5 bg-white/90 text-sm text-gray-600 rounded-lg shadow-sm border border-gray-200">
          Click to edit
        </span>
      </div>
    </div>
  );
}

