'use client';

import { useState, useEffect } from 'react';
import { X, Plus, Trash2, GripVertical } from 'lucide-react';

interface KnowledgeCheckEditorProps {
  type: 'MultipleChoiceBlock' | 'FillInTheBlankBlock' | 'MatchingPairsBlock' | 'SortingBlock';
  data: Record<string, unknown>;
  onSave: (data: Record<string, unknown>) => void;
  onClose: () => void;
}

export function KnowledgeCheckEditor({ type, data, onSave, onClose }: KnowledgeCheckEditorProps) {
  const [editData, setEditData] = useState<Record<string, unknown>>(JSON.parse(JSON.stringify(data)));

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [onClose]);

  const handleSave = () => {
    onSave(editData);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50 backdrop-blur-sm" onClick={onClose} />

      <div className="relative w-full max-w-2xl max-h-[85vh] bg-white rounded-2xl shadow-2xl overflow-hidden mx-4 flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-gray-200">
          <h3 className="text-lg font-semibold text-gray-900">
            Edit {getTypeLabel(type)}
          </h3>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg hover:bg-gray-100 transition-colors text-gray-500"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {type === 'MultipleChoiceBlock' && (
            <MCEditor
              data={editData}
              onChange={setEditData}
              isMultiResponse={false}
            />
          )}
          {type === 'FillInTheBlankBlock' && (
            <FillInBlankEditor data={editData} onChange={setEditData} />
          )}
          {type === 'MatchingPairsBlock' && (
            <MatchingPairsEditor data={editData} onChange={setEditData} />
          )}
          {type === 'SortingBlock' && (
            <SortingEditor data={editData} onChange={setEditData} />
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-gray-200 bg-gray-50">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-gray-700 hover:bg-gray-200 rounded-lg transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleSave}
            className="px-4 py-2 text-sm font-medium text-white bg-[#9F80DA] hover:bg-[#8A6BC5] rounded-lg transition-colors"
          >
            Save changes
          </button>
        </div>
      </div>
    </div>
  );
}

function getTypeLabel(type: string): string {
  const labels: Record<string, string> = {
    MultipleChoiceBlock: 'Multiple Choice',
    FillInTheBlankBlock: 'Fill in the Blank',
    MatchingPairsBlock: 'Matching Pairs',
    SortingBlock: 'Sorting',
  };
  return labels[type] || type;
}

// MC/MR Editor
function MCEditor({
  data,
  onChange,
  isMultiResponse,
}: {
  data: Record<string, unknown>;
  onChange: (data: Record<string, unknown>) => void;
  isMultiResponse: boolean;
}) {
  const question = String(data.question || '');
  const options = (data.options as Array<{ text: string; isCorrect: boolean }>) || [];

  const updateQuestion = (value: string) => {
    onChange({ ...data, question: value });
  };

  const updateOption = (index: number, field: 'text' | 'isCorrect', value: string | boolean) => {
    const newOptions = [...options];
    if (field === 'isCorrect' && !isMultiResponse) {
      // Single choice: deselect all others
      newOptions.forEach((opt, i) => {
        newOptions[i] = { ...opt, isCorrect: i === index };
      });
    } else {
      newOptions[index] = { ...newOptions[index], [field]: value };
    }
    onChange({ ...data, options: newOptions });
  };

  const addOption = () => {
    onChange({
      ...data,
      options: [...options, { text: '', isCorrect: false }],
    });
  };

  const removeOption = (index: number) => {
    onChange({
      ...data,
      options: options.filter((_, i) => i !== index),
    });
  };

  return (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">Question</label>
        <textarea
          value={question}
          onChange={(e) => updateQuestion(e.target.value)}
          rows={3}
          className="w-full px-4 py-3 text-sm border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#9F80DA] resize-none"
          placeholder="Enter question..."
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Options {isMultiResponse ? '(select all correct)' : '(select one correct)'}
        </label>
        <div className="space-y-2">
          {options.map((opt, idx) => (
            <div key={idx} className="flex items-center gap-2">
              <input
                type={isMultiResponse ? 'checkbox' : 'radio'}
                name="correct-option"
                checked={opt.isCorrect}
                onChange={(e) => updateOption(idx, 'isCorrect', e.target.checked)}
                className="accent-[#9F80DA]"
              />
              <input
                type="text"
                value={opt.text}
                onChange={(e) => updateOption(idx, 'text', e.target.value)}
                className="flex-1 px-3 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#9F80DA]"
                placeholder={`Option ${idx + 1}`}
              />
              <button
                onClick={() => removeOption(idx)}
                className="p-1.5 text-gray-400 hover:text-red-500 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={addOption}
          className="flex items-center gap-1 mt-2 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          <Plus className="w-4 h-4" />
          Add option
        </button>
      </div>
    </div>
  );
}

// Fill in the blank Editor
function FillInBlankEditor({
  data,
  onChange,
}: {
  data: Record<string, unknown>;
  onChange: (data: Record<string, unknown>) => void;
}) {
  const text = String(data.text || '');
  const blanks = (data.blanks as string[]) || [];

  return (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Text (use ___ for blanks)
        </label>
        <textarea
          value={text}
          onChange={(e) => onChange({ ...data, text: e.target.value })}
          rows={4}
          className="w-full px-4 py-3 text-sm border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#9F80DA] resize-none"
          placeholder="The ___ jumped over the ___ dog."
        />
      </div>

      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Correct answers (in order)
        </label>
        <div className="space-y-2">
          {blanks.map((blank, idx) => (
            <div key={idx} className="flex items-center gap-2">
              <span className="text-sm text-gray-500 w-12">Blank {idx + 1}:</span>
              <input
                type="text"
                value={blank}
                onChange={(e) => {
                  const newBlanks = [...blanks];
                  newBlanks[idx] = e.target.value;
                  onChange({ ...data, blanks: newBlanks });
                }}
                className="flex-1 px-3 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#9F80DA]"
                placeholder="Answer..."
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// Matching Pairs Editor
function MatchingPairsEditor({
  data,
  onChange,
}: {
  data: Record<string, unknown>;
  onChange: (data: Record<string, unknown>) => void;
}) {
  const pairs = (data.pairs as Array<{ left: string; right: string }>) || [];

  const updatePair = (index: number, side: 'left' | 'right', value: string) => {
    const newPairs = [...pairs];
    newPairs[index] = { ...newPairs[index], [side]: value };
    onChange({ ...data, pairs: newPairs });
  };

  const addPair = () => {
    onChange({ ...data, pairs: [...pairs, { left: '', right: '' }] });
  };

  const removePair = (index: number) => {
    onChange({ ...data, pairs: pairs.filter((_, i) => i !== index) });
  };

  return (
    <div className="space-y-4">
      <label className="block text-sm font-medium text-gray-700">Matching Pairs</label>
      <div className="space-y-2">
        {pairs.map((pair, idx) => (
          <div key={idx} className="flex items-center gap-2">
            <input
              type="text"
              value={pair.left}
              onChange={(e) => updatePair(idx, 'left', e.target.value)}
              className="flex-1 px-3 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#9F80DA]"
              placeholder="Left item"
            />
            <span className="text-gray-400">↔</span>
            <input
              type="text"
              value={pair.right}
              onChange={(e) => updatePair(idx, 'right', e.target.value)}
              className="flex-1 px-3 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#9F80DA]"
              placeholder="Right item"
            />
            <button
              onClick={() => removePair(idx)}
              className="p-1.5 text-gray-400 hover:text-red-500 transition-colors"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ))}
      </div>
      <button
        onClick={addPair}
        className="flex items-center gap-1 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
      >
        <Plus className="w-4 h-4" />
        Add pair
      </button>
    </div>
  );
}

// Sorting Editor
function SortingEditor({
  data,
  onChange,
}: {
  data: Record<string, unknown>;
  onChange: (data: Record<string, unknown>) => void;
}) {
  const items = (data.items as string[]) || (data.steps as string[]) || [];
  const field = data.items !== undefined ? 'items' : 'steps';

  const updateItem = (index: number, value: string) => {
    const newItems = [...items];
    newItems[index] = value;
    onChange({ ...data, [field]: newItems });
  };

  const addItem = () => {
    onChange({ ...data, [field]: [...items, ''] });
  };

  const removeItem = (index: number) => {
    onChange({ ...data, [field]: items.filter((_, i) => i !== index) });
  };

  return (
    <div className="space-y-4">
      <div>
        {data.question !== undefined && (
          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-1">Question</label>
            <textarea
              value={String(data.question || '')}
              onChange={(e) => onChange({ ...data, question: e.target.value })}
              rows={2}
              className="w-full px-4 py-3 text-sm border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#9F80DA] resize-none"
              placeholder="Enter question..."
            />
          </div>
        )}

        <label className="block text-sm font-medium text-gray-700 mb-2">
          Items (in correct order)
        </label>
        <div className="space-y-2">
          {items.map((item, idx) => (
            <div key={idx} className="flex items-center gap-2">
              <GripVertical className="w-4 h-4 text-gray-300" />
              <span className="text-sm text-gray-500 w-6">{idx + 1}.</span>
              <input
                type="text"
                value={item}
                onChange={(e) => updateItem(idx, e.target.value)}
                className="flex-1 px-3 py-2 text-sm border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#9F80DA]"
                placeholder={`Item ${idx + 1}`}
              />
              <button
                onClick={() => removeItem(idx)}
                className="p-1.5 text-gray-400 hover:text-red-500 transition-colors"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        </div>
        <button
          onClick={addItem}
          className="flex items-center gap-1 mt-2 text-sm text-[#9F80DA] hover:text-[#8A6BC5] font-medium"
        >
          <Plus className="w-4 h-4" />
          Add item
        </button>
      </div>
    </div>
  );
}
